import {numberCell,validateData,renderChart} from './research-model.mjs';
const xml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export const researchSessionKey='paperknow-research-session-v2';
export function validateDiagram(value){
 if(!value||typeof value!=='object'||!Array.isArray(value.nodes)||!Array.isArray(value.edges))throw Error('结构图需要实际节点与连接关系。');
 const title=String(value.title||'').trim();if(!title||title.length>120)throw Error('结构图标题需为 1–120 字。');
 if(!value.nodes.length||value.nodes.length>30||value.edges.length>60)throw Error('结构示意图支持 1–30 个节点、最多 60 条连接。');
 const ids=new Set();const nodes=value.nodes.map((node,index)=>{const id=String(node.id||'').trim(),label=String(node.label||'').trim();if(!/^[a-zA-Z0-9_-]{1,60}$/.test(id)||ids.has(id))throw Error(`第 ${index+1} 个节点的标识为空、重复或无效。`);if(!label||label.length>100)throw Error(`第 ${index+1} 个节点名称需要 1–100 字。`);ids.add(id);return {id,label};});
 const edges=value.edges.map((edge,index)=>{const from=String(edge.from||''),to=String(edge.to||''),label=String(edge.label||'').trim();if(!ids.has(from)||!ids.has(to))throw Error(`第 ${index+1} 条连接指向不存在的节点。`);if(from===to)throw Error('暂不支持自连接，请用节点说明表达反馈。');if(label.length>60)throw Error('连接说明最多 60 字。');return {from,to,label};});return {title,nodes,edges};
}
export function parseDiagramText(title,nodesText,edgesText){const nodes=String(nodesText||'').split(/\r?\n/).filter(line=>line.trim()).map(line=>{const i=line.indexOf('|');if(i<1)throw Error('节点格式为：标识 | 节点名称，每行一个。');return {id:line.slice(0,i).trim(),label:line.slice(i+1).trim()};});const edges=String(edgesText||'').split(/\r?\n/).filter(line=>line.trim()).map(line=>{const fields=line.split('|').map(x=>x.trim());if(fields.length<2||fields.length>3)throw Error('连接格式为：起点标识 | 终点标识 | 关系说明（可选）。');return {from:fields[0],to:fields[1],label:fields[2]||''};});return validateDiagram({title,nodes,edges});}
function splitLabel(label,width){return Array.from(label).reduce((lines,char)=>{if(lines.at(-1).length>=width)lines.push('');lines[lines.length-1]+=char;return lines;},['']).slice(0,5);}
export function renderDiagram(value){const diagram=validateDiagram(value),cols=Math.min(3,Math.max(1,Math.ceil(Math.sqrt(diagram.nodes.length)))),rows=Math.ceil(diagram.nodes.length/cols),width=1200,height=Math.max(440,190+rows*160),bw=290,bh=92,gap=(width-cols*bw)/(cols+1),coordinates=new Map(diagram.nodes.map((node,index)=>[node.id,{x:gap+(index%cols)*(bw+gap),y:120+Math.floor(index/cols)*160}]));let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${xml(diagram.title)}"><title>${xml(diagram.title)}</title><desc>结构示意图。节点与关系需人工核对，不是实验、仿真或工程计算结果。</desc><defs><marker id="research-arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto-start-reverse"><path d="M0 0L9 4.5L0 9" fill="#647db4"/></marker></defs><rect width="${width}" height="${height}" fill="white"/><text x="600" y="48" text-anchor="middle" font-family="Arial,Microsoft YaHei,sans-serif" font-size="25" font-weight="700" fill="#203659">${xml(diagram.title)}</text><g font-family="Arial,Microsoft YaHei,sans-serif">`;
 for(const edge of diagram.edges){const a=coordinates.get(edge.from),b=coordinates.get(edge.to),ax=a.x+bw/2,ay=a.y+bh/2,bx=b.x+bw/2,by=b.y+bh/2,dx=bx-ax,dy=by-ay,t=Math.min((bw/2)/Math.max(1,Math.abs(dx)),(bh/2)/Math.max(1,Math.abs(dy))),s=Math.min((bw/2+10)/Math.max(1,Math.abs(dx)),(bh/2+10)/Math.max(1,Math.abs(dy))),x1=ax+dx*t,y1=ay+dy*t,x2=bx-dx*s,y2=by-dy*s;svg+=`<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="#647db4" stroke-width="2.2" marker-end="url(#research-arrow)"/>`;if(edge.label){const x=(x1+x2)/2,y=(y1+y2)/2;svg+=`<rect x="${x-Math.min(210,edge.label.length*6)}" y="${y-18}" width="${Math.min(420,edge.label.length*12)}" height="25" fill="white" opacity=".95"/><text x="${x}" y="${y}" text-anchor="middle" font-size="13" fill="#46618a">${xml(edge.label)}</text>`;}}
 for(const [index,node]of diagram.nodes.entries()){const p=coordinates.get(node.id),lines=splitLabel(node.label,18);svg+=`<g data-node-id="${xml(node.id)}"><rect x="${p.x}" y="${p.y}" width="${bw}" height="${bh}" rx="15" fill="${index%2?'#F0F9F7':'#EFF4FF'}" stroke="${index%2?'#B6DFD6':'#B7CCFA'}" stroke-width="1.5"/><text x="${p.x+bw/2}" y="${p.y+bh/2-(lines.length-1)*9}" font-size="16" fill="#203659" text-anchor="middle">${lines.map((line,i)=>`<tspan x="${p.x+bw/2}" dy="${i?18:0}">${xml(line)}</tspan>`).join('')}</text></g>`;}return svg+`<text x="1160" y="${height-25}" text-anchor="end" font-size="12" fill="#8B9BB1">PaperKnow · 结构示意，待核对</text></g></svg>`;
}
export function applyChartAdvice(current,advice){if(!advice||typeof advice!=='object')throw Error('未返回有效图表配置。');validateData(current);if(JSON.stringify(advice.headers)!==JSON.stringify(current.headers)||JSON.stringify(advice.rows?.map(row=>row.map(String)))!==JSON.stringify(current.rows.map(row=>row.map(String))))throw Error('建议中的数据与当前表格不一致，未应用。请重新生成，原始数据不会被改写。');const next={...current};for(const key of ['type','title','xLabel','yLabel','unit'])if(advice[key]!==undefined)next[key]=String(advice[key]);renderChart(next);return next;}
export function describeResearchData(chart){const rows=chart.rows,series=chart.headers.slice(1).map((name,index)=>{const values=[];let missing=0;for(const row of rows){const value=String(row[index+1]??'').trim();if(!value){missing++;continue;}values.push(numberCell(value,'「'+name+'」中的非空值'));}const n=values.length,mean=n?values.reduce((sum,v)=>sum+v,0)/n:null;return {name,n,missing,mean,sd:n>1?Math.sqrt(values.reduce((sum,v)=>sum+(v-mean)**2,0)/(n-1)):null,min:n?Math.min(...values):null,max:n?Math.max(...values):null};});return series;}
export function validateFormulaCode(value){const latex=String(value||'').trim();if(!latex||latex.length>2000)throw Error('公式需要 1–2000 字符。');if(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/.test(latex))throw Error('公式包含不可用字符。');if(/\\(?:label|ref|eqref|tag|href|url|includegraphics|html\w*|style|class|cssId|require|autoload|newcommand|renewcommand|providecommand|def|gdef|edef|xdef|let|futurelet|csname|expandafter|input|include|write|openout|catcode)\b/i.test(latex))throw Error('公式仅支持数学排版，不支持外链、HTML、文件、宏定义、跨公式引用或动态扩展。');return latex;}
